r=b.OUT/'investigation';out=r/'positivity48';results=json.loads((out/'results.json').read_text());modes=pd.DataFrame(json.loads((out/'uniform_mode_results.json').read_text()));trace=dict(np.load(out/'onset_trace.npz'))['trace']
fig=make_subplots(rows=2,cols=2,subplot_titles=['Outlet hydrographs: full discharge scale','MC and 100 m reference: timing calibration only','Original 50 m run: depth extremes before first failure','Controlled uniform channel: disturbance after one hour'],vertical_spacing=.16,horizontal_spacing=.10)
base=pd.read_parquet(out/'100m_cfl035/wave.parquet');lo=base.time_utc.min();hi=base.time_utc.max()
def add(w,name,color,dash='solid',columns=(1,2)):
    z=w[(w.time_utc>=lo)&(w.time_utc<=hi)];indices={0,len(z)-1};q=z.q_outlet_cms.to_numpy()
    for i in range(0,len(z),10):indices.update([i+int(np.argmin(q[i:i+10])),i+int(np.argmax(q[i:i+10]))])
    z=z.iloc[sorted(indices)]
    for col in columns:fig.add_trace(go.Scatter(x=z.time_utc,y=z.q_outlet_cms,name=name,legendgroup=name,showlegend=col==1,line=dict(color=color,dash=dash)),row=1,col=col)
